onChange:
function onChange(value, rowNum, parentRowNum) {
  if ((value === null ? "" : value).indexOf("READY") >= 0) {
    MKXFORM.setValue("fd_marker", "active");
  } else {
    MKXFORM.setValue("fd_marker", "inactive");
  }
}

